# generated by tools/ail2py.py from callback_text_rewrite_main.ail; edit the .ail until onelang s16
from callback_text_pipeline import *
from ail import read_bytes, write_bytes
import sys

def trim_line(line: str) -> str:
    return line.strip()

def frame_line(line: str) -> str:
    return '[' + line + ']'

# Decode and encode UTF-8 explicitly; no platform newline translation.
def main() -> int:
    if len(sys.argv) != 4:
        print('usage: callback_text_rewrite <utf8-input> <utf8-output> trim|frame', file=sys.stderr)
        return 2
    mode = sys.argv[3]
    if mode != 'trim' and mode != 'frame':
        print('mode must be trim or frame', file=sys.stderr)
        return 2
    try:
        text = read_bytes(sys.argv[1]).decode()
        output = ''
        if mode == 'trim':
            output = rewrite_lines(text, trim_line)
        else:
            output = rewrite_lines(text, frame_line)
        write_bytes(sys.argv[2], output.encode())
        return 0
    except UnicodeDecodeError:
        print('input must be UTF-8', file=sys.stderr)
        return 4
    except ValueError:
        print('invalid text transformation', file=sys.stderr)
        return 4
    except OSError:
        print('text rewrite file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
